class Solution:
    def findBall(self, grid: list[list[int]]) -> list[int]:
        m, n = len(grid), len(grid[0])
        ans = []
        for col in range(n):
            curr = col
            for r in range(m):
                d = grid[r][curr]
                nxt = curr + d
                if nxt < 0 or nxt >= n or grid[r][nxt] != d:
                    curr = -1
                    break
                curr = nxt
            ans.append(curr)
        return ans

#include <vector>
using namespace std;

class Solution {
public:
    vector<int> findBall(vector<vector<int>>& grid) {
        int m = grid.size();
        int n = grid[0].size();
        vector<int> ans(n);
        for (int col = 0; col < n; ++col) {
            int curr = col;
            for (int r = 0; r < m; ++r) {
                int d = grid[r][curr];
                int nxt = curr + d;
                if (nxt < 0 || nxt >= n || grid[r][nxt] != d) {
                    curr = -1;
                    break;
                }
                curr = nxt;
            }
            ans[col] = curr;
        }
        return ans;
    }
};

